export default function CircuitProjectPage() {
  return (
    <main
      style={{
        padding: "120px 60px",
        color: "white",
        maxWidth: "900px",
        margin: "0 auto",
      }}
    >
      {/* HEADER */}
      <section style={{ marginBottom: "60px" }}>
        <h1 style={{ fontSize: "42px", marginBottom: "10px" }}>
          Real-Time Circuit Simulation
        </h1>

        <p style={muted}>
          A system that renders a car moving along a circuit using{" "}
          <strong>path interpolation</strong> and{" "}
          <strong>canvas-based animation</strong>.
        </p>
      </section>

      {/* CONTEXT */}
      <section style={section}>
        <h2 style={title}>Context</h2>

        <p style={text}>
          This project started as a way to represent an F1 circuit in a more{" "}
          <strong>visual and interactive</strong> way.
        </p>

        <p style={text}>
          Instead of a static image, I wanted something with{" "}
          <strong>movement</strong> and a bit more depth.
        </p>
      </section>

      {/* PROBLEM */}
      <section style={section}>
        <h2 style={title}>Problem</h2>

        <p style={text}>
          A basic animation wasn’t enough. The goal was to make the car follow
          the track in a <strong>smooth and continuous</strong> way, without
          jumps or unnatural movement.
        </p>
      </section>

      {/* SOLUTION */}
      <section style={section}>
        <h2 style={title}>Solution</h2>

        <p style={text}>
          I built a system based on <strong>points</strong> representing the
          center of the track.
        </p>

        <p style={text}>
          From there, I interpolate positions between segments to move the car
          smoothly along the circuit.
        </p>
      </section>

      {/* REAL DETAIL */}
      <section style={section}>
        <h2 style={title}>Real-world reference</h2>

        <p style={text}>
          The car speed is calibrated so that a full lap matches the real track
          record:
        </p>

        <p style={highlight}>
          1:14.637 — Michael Schumacher (Ferrari, 2006)
        </p>
      </section>

      {/* HOW IT WORKS */}
      <section style={section}>
        <h2 style={title}>How it works</h2>

        <ul style={list}>
          <li>
            The track is defined as a <strong>set of points</strong>
          </li>
          <li>
            Total distance is calculated across all segments
          </li>
          <li>
            The car moves using <strong>distance-based interpolation</strong>
          </li>
          <li>
            Animation runs with <strong>requestAnimationFrame</strong>
          </li>
          <li>
            Rendering is handled via <strong>Canvas API</strong>
          </li>
        </ul>
      </section>

      {/* CHALLENGES */}
      <section style={section}>
        <h2 style={title}>Challenges</h2>

        <p style={text}>
          One of the main challenges was achieving{" "}
          <strong>fully smooth motion</strong> across the entire track.
        </p>

        <p style={text}>
          It also required careful tuning to avoid{" "}
          <strong>visible jumps between segments</strong>.
        </p>
      </section>

      {/* LEARNINGS */}
      <section style={section}>
        <h2 style={title}>What I learned</h2>

        <p style={text}>
          This project helped me better understand{" "}
          <strong>canvas animations</strong> and how to structure a{" "}
          <strong>trajectory-based system</strong>.
        </p>

        <p style={text}>
          It also reinforced concepts related to{" "}
          <strong>geometry</strong> and{" "}
          <strong>real-time rendering</strong>.
        </p>
      </section>

      {/* TECH */}
      <section style={section}>
        <h2 style={title}>Technologies</h2>

        <div style={tags}>
          {[
            "JavaScript",
            "TypeScript",
            "Canvas API",
            "requestAnimationFrame",
          ].map((t) => (
            <span key={t} style={tag}>
              {t}
            </span>
          ))}
        </div>
      </section>
    </main>
  );
}

/* 🎨 STYLES */

const section: React.CSSProperties = {
  marginBottom: "50px",
};

const title: React.CSSProperties = {
  marginBottom: "10px",
  fontSize: "22px",
};

const text: React.CSSProperties = {
  opacity: 0.75,
  marginBottom: "10px",
  lineHeight: "1.6",
};

const muted: React.CSSProperties = {
  opacity: 0.7,
  maxWidth: "600px",
};

const highlight: React.CSSProperties = {
  marginTop: "10px",
  fontWeight: "600",
  color: "#e11d48",
};

const list: React.CSSProperties = {
  opacity: 0.75,
  paddingLeft: "20px",
  lineHeight: "1.6",
};

const tags: React.CSSProperties = {
  display: "flex",
  gap: "10px",
  flexWrap: "wrap",
};

const tag: React.CSSProperties = {
  padding: "6px 12px",
  borderRadius: "999px",
  background: "#1e293b",
  fontSize: "12px",
};